BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path=public,extensions;
SELECT plan(20);
INSERT INTO auth.users(id,email) VALUES ('f0000000-0000-0000-0000-000000000001','m3-a@example.test'),('f0000000-0000-0000-0000-000000000002','m3-b@example.test');
SELECT public.merchant_search_cache_v1('f0000000-0000-0000-0000-000000000001','m3', '[{"name":"M3 Brand","domain":"m3.test","logo_url":null},{"name":"Excluded","domain":"tambo.pe","logo_url":null}]');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);
SELECT lives_ok($$SELECT public.add_merchant_from_logo_dev_v1('m3','m3.test')$$,'cached candidate can be added');
SELECT is((SELECT count(*)::int FROM public.merchant_services WHERE domain='m3.test'),1,'global exists');
SELECT is((public.add_merchant_from_logo_dev_v1('m3','m3.test')->>'needs_logo_sync')::boolean,true,'idempotent pending add remains eligible for logo retry');
SELECT throws_ok($$SELECT public.add_merchant_from_logo_dev_v1('m3','uncached.test')$$,'P0001','CANDIDATE_NOT_CACHED','forged candidate rejected');
SELECT throws_ok($$SELECT public.add_merchant_from_logo_dev_v1('m3','tambo.pe')$$,'P0001','DOMAIN_EXCLUDED','rejected Logo.dev domain stays excluded');
SELECT lives_ok($$SELECT public.create_private_merchant_v1('My M3 Shop')$$,'private created');
SELECT is(public.create_private_merchant_v1('my m3 shop')->>'id',(SELECT id::text FROM public.merchant_services WHERE name='My M3 Shop'),'private name idempotent');
SELECT is(public.create_private_merchant_v1('M3 Brand')->>'id',(SELECT id::text FROM public.merchant_services WHERE domain='m3.test'),'private reuses global normalized name');
SELECT throws_ok($$SELECT public.create_private_merchant_v1('CVV 123')$$,'P0001','INVALID_MERCHANT_NAME','CVV rejected');
SELECT throws_ok($$SELECT public.create_private_merchant_v1('4111 1111 1111 1111')$$,'P0001','INVALID_MERCHANT_NAME','PAN rejected');
SELECT throws_ok($$INSERT INTO public.merchant_services(name,normalized_name,user_id,is_system) VALUES('Forged','forged','f0000000-0000-0000-0000-000000000001',true)$$,'42501',NULL,'direct global insert denied');
SELECT set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);
SELECT is((SELECT count(*)::int FROM public.merchant_services WHERE domain='m3.test'),1,'global visible to second user');
SELECT is((SELECT count(*)::int FROM public.merchant_services WHERE name='My M3 Shop'),0,'private invisible to second user');
SELECT throws_ok($$SELECT public.add_merchant_from_logo_dev_v1('m3','m3.test')$$,'P0001','CANDIDATE_NOT_CACHED','cache cannot be borrowed from another user');
RESET ROLE;
INSERT INTO internal.merchant_discovery_events(user_id,kind) SELECT 'f0000000-0000-0000-0000-000000000002','SEARCH' FROM generate_series(1,20);
SELECT throws_ok($$SELECT public.merchant_search_cache_v1('f0000000-0000-0000-0000-000000000002','quota')$$,'P0001','MERCHANT_RATE_LIMITED','hourly search limit enforced');
INSERT INTO internal.merchant_discovery_events(user_id,kind,created_at) SELECT 'f0000000-0000-0000-0000-000000000001','SEARCH',now()-interval '2 hours' FROM generate_series(1,100);
SELECT throws_ok($$SELECT public.merchant_search_cache_v1('f0000000-0000-0000-0000-000000000001','quota')$$,'P0001','MERCHANT_RATE_LIMITED','daily search limit enforced');
INSERT INTO internal.merchant_discovery_events(user_id,kind) SELECT 'f0000000-0000-0000-0000-000000000002','ADD' FROM generate_series(1,10);
SELECT public.merchant_search_cache_v1('f0000000-0000-0000-0000-000000000002','second','[{"name":"Second","domain":"second-m3.test"}]');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);
SELECT throws_ok($$SELECT public.add_merchant_from_logo_dev_v1('second','second-m3.test')$$,'P0001','MERCHANT_RATE_LIMITED','daily add limit enforced');
RESET ROLE;
UPDATE internal.merchant_search_access SET expires_at=now()-interval '1 second' WHERE user_id='f0000000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);
SELECT throws_ok($$SELECT public.add_merchant_from_logo_dev_v1('m3','m3.test')$$,'P0001','CANDIDATE_NOT_CACHED','expired user authorization rejected');
SELECT is((SELECT count(*)::int FROM public.merchant_services WHERE name='My M3 Shop'),1,'owner can read own private merchant');
RESET ROLE;
DELETE FROM internal.merchant_discovery_events WHERE user_id='f0000000-0000-0000-0000-000000000001' AND kind='SEARCH';
SELECT public.merchant_search_cache_v1('f0000000-0000-0000-0000-000000000001','inflight');
SELECT throws_ok($$SELECT public.merchant_search_cache_v1('f0000000-0000-0000-0000-000000000001','inflight')$$,'P0001','SEARCH_BUSY','simultaneous cache misses coalesce');
SELECT * FROM finish();
ROLLBACK;
